//! Golden regression for the system-one request, prompt, and answer layer
//! against the reference implementation's own output on the decider-0.8b
//! tokenizer.
//!
//! The fixtures are generated by the reference code (the checkpoint's server
//! path) and carry, for each request, every row's token ids, slots, option
//! counts, and the reported input-token count; separately, for each answer, the
//! reference `assemble` output over given probability rows. The port must
//! reproduce all of them exactly: one differing id fails.
//!
//! **Checkpoint gate**: this test needs the checkpoint tokenizer. Set
//! `LATTICE_DECIDER_DIR` to a directory holding `tokenizer.json` and
//! `decider_config.json`. When it is unset or the directory is missing, the test
//! prints a skip reason and returns; when `LATTICE_DECIDER_GATE_ENFORCE=1` is
//! set, a missing checkpoint panics instead, so a provisioning failure cannot
//! masquerade as a pass.
//!
//! **Population**: the 40 committed edge requests and their answers always run.
//! When `LATTICE_SYSTEMONE_SAMPLE_DIR` names a directory holding
//! `sample_requests.jsonl` and `sample_answers.jsonl`, that population runs too
//! and its absence is only a printed skip reason.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use indexmap::IndexMap;
use lattice_inference::option_scoring::resolve_decision_labels;
use lattice_inference::serve::systemone::answer::AnswerValue;
use lattice_inference::serve::systemone::{
    DeciderConfig, assemble, load_decider_config, prepare_request,
};
use lattice_inference::tokenizer::BpeTokenizer;
use serde::Deserialize;
use serde_json::Value;

const SKIP_MARKER: &str = "LATTICE_SYSTEMONE_SKIPPED";
const ENFORCE_ENV: &str = "LATTICE_DECIDER_GATE_ENFORCE";
const DECIDER_DIR_ENV: &str = "LATTICE_DECIDER_DIR";
const SAMPLE_DIR_ENV: &str = "LATTICE_SYSTEMONE_SAMPLE_DIR";
const NUMBER_TOLERANCE: f64 = 1e-4;

#[derive(Deserialize)]
struct LabelTable {
    labels: Vec<String>,
    ids: Vec<u32>,
}

#[derive(Deserialize)]
struct RowFixture {
    ids: Vec<u32>,
    slots: Vec<usize>,
    nopts: Vec<usize>,
}

#[derive(Deserialize)]
struct IndexFixture(String, String, usize, usize);

#[derive(Deserialize)]
struct RequestFixture {
    name: String,
    request_json: String,
    ok: bool,
    #[serde(default)]
    error: Option<String>,
    #[serde(default)]
    rows: Option<Vec<RowFixture>>,
    #[serde(default)]
    index: Option<Vec<IndexFixture>>,
    #[serde(default)]
    unique_tokens: Option<usize>,
    #[serde(default)]
    state_tokens: Option<usize>,
    #[serde(default)]
    truncated: Option<bool>,
}

#[derive(Deserialize)]
struct AnswerFixture {
    name: String,
    request_json: String,
    probs: Vec<Vec<f64>>,
    answers: Value,
}

fn enforce() -> bool {
    std::env::var(ENFORCE_ENV).is_ok()
}

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("systemone_decider_0_8b")
}

/// The checkpoint tokenizer and config, or `None` (with a printed reason) when
/// the checkpoint is absent and the gate is not enforced.
fn checkpoint(test: &str) -> Option<(BpeTokenizer, DeciderConfig)> {
    let Some(dir) = std::env::var_os(DECIDER_DIR_ENV).map(PathBuf::from) else {
        return absent(test, "LATTICE_DECIDER_DIR is unset");
    };
    let tokenizer_path = dir.join("tokenizer.json");
    let config_path = dir.join("decider_config.json");
    if !tokenizer_path.is_file() || !config_path.is_file() {
        return absent(
            test,
            &format!(
                "{} has no tokenizer.json/decider_config.json",
                dir.display()
            ),
        );
    }
    let tokenizer = match BpeTokenizer::from_tokenizer_json(&tokenizer_path) {
        Ok(tokenizer) => tokenizer.with_max_seq_len(usize::MAX),
        Err(error) => {
            if enforce() {
                panic!("{ENFORCE_ENV}=1 but the tokenizer failed to load: {error}");
            }
            eprintln!("{SKIP_MARKER} test={test} reason=tokenizer load failed: {error}");
            return None;
        }
    };
    let config = match load_decider_config(&dir) {
        Ok(config) => config,
        Err(error) => {
            if enforce() {
                panic!("{ENFORCE_ENV}=1 but the config failed to load: {error}");
            }
            eprintln!("{SKIP_MARKER} test={test} reason=config load failed: {error}");
            return None;
        }
    };
    Some((tokenizer, config))
}

fn absent(test: &str, reason: &str) -> Option<(BpeTokenizer, DeciderConfig)> {
    if enforce() {
        panic!("{ENFORCE_ENV}=1 but the checkpoint is unavailable: {reason}");
    }
    eprintln!("{SKIP_MARKER} test={test} reason={reason}");
    None
}

fn read_jsonl<T: for<'de> Deserialize<'de>>(path: &Path) -> Vec<T> {
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
    text.lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| {
            serde_json::from_str(line)
                .unwrap_or_else(|error| panic!("parse a line of {}: {error}", path.display()))
        })
        .collect()
}

#[test]
fn label_table_matches_the_reference() {
    let Some((tokenizer, config)) = checkpoint("label_table_matches_the_reference") else {
        return;
    };
    let expected: LabelTable = serde_json::from_str(
        &std::fs::read_to_string(fixture_dir().join("label_table.json")).expect("read label table"),
    )
    .expect("parse label table");
    let table = resolve_decision_labels(&tokenizer, config.max_options).expect("resolve labels");
    assert_eq!(table.labels, expected.labels, "label spellings differ");
    assert_eq!(table.ids, expected.ids, "label token ids differ");
    assert_eq!(table.labels.len(), 255);
    assert_eq!(
        table.labels.iter().filter(|label| label.len() == 1).count(),
        26
    );
    eprintln!(
        "systemone label table: {} entries, {} distinct ids, last {}",
        table.labels.len(),
        table.ids.iter().collect::<BTreeSet<_>>().len(),
        table.labels.last().map(String::as_str).unwrap_or(""),
    );
}

#[test]
fn edge_requests_reproduce_the_reference_rows() {
    let Some((tokenizer, config)) = checkpoint("edge_requests_reproduce_the_reference_rows") else {
        return;
    };
    let labels = resolve_decision_labels(&tokenizer, config.max_options).expect("resolve labels");
    let fixtures: Vec<RequestFixture> = read_jsonl(&fixture_dir().join("edge_requests.jsonl"));
    let mut requests_checked = 0usize;
    let mut rows_checked = 0usize;
    let mut ids_compared = 0usize;
    let mut refusals_checked = 0usize;
    for fixture in &fixtures {
        requests_checked += 1;
        let prepared = prepare_request(&tokenizer, &labels, &config, &fixture.request_json);
        if fixture.ok {
            let prepared = prepared.unwrap_or_else(|error| {
                panic!("{}: must be accepted, refused with {error}", fixture.name)
            });
            let expected_rows = fixture.rows.as_ref().expect("ok fixture has rows");
            assert_eq!(
                prepared.prompt.rows.len(),
                expected_rows.len(),
                "{}: row count",
                fixture.name
            );
            for (row, expected) in prepared.prompt.rows.iter().zip(expected_rows) {
                assert_eq!(row.ids, expected.ids, "{}: ids", fixture.name);
                assert_eq!(row.slot, expected.slots[0], "{}: slot", fixture.name);
                assert_eq!(row.nopts, expected.nopts[0], "{}: nopts", fixture.name);
                rows_checked += 1;
                ids_compared += expected.ids.len();
            }
            assert_eq!(
                prepared.prompt.unique_tokens(),
                fixture.unique_tokens.expect("ok fixture has unique_tokens"),
                "{}: unique_tokens",
                fixture.name
            );
            assert_eq!(
                prepared.prompt.state_tokens,
                fixture.state_tokens.expect("ok fixture has state_tokens"),
                "{}: state_tokens",
                fixture.name
            );
            assert_eq!(
                prepared.prompt.truncated,
                fixture.truncated.expect("ok fixture has truncated"),
                "{}: truncated",
                fixture.name
            );
            let expected_index = fixture.index.as_ref().expect("ok fixture has index");
            assert_eq!(
                prepared.index.len(),
                expected_index.len(),
                "{}: index len",
                fixture.name
            );
            for (entry, expected) in prepared.index.iter().zip(expected_index) {
                assert_eq!(entry.id, expected.0, "{}: index id", fixture.name);
                let kind = match entry.kind {
                    lattice_inference::serve::systemone::RowKind::Isolated => "iso",
                    lattice_inference::serve::systemone::RowKind::List => "list",
                };
                assert_eq!(kind, expected.1, "{}: index kind", fixture.name);
                assert_eq!(entry.first, expected.2, "{}: index first", fixture.name);
                assert_eq!(entry.count, expected.3, "{}: index count", fixture.name);
            }
        } else {
            let error = prepared.expect_err(&fixture.name);
            let expected = fixture.error.as_ref().expect("error fixture has error");
            assert_eq!(
                error.to_string(),
                *expected,
                "{}: refusal message",
                fixture.name
            );
            refusals_checked += 1;
        }
    }
    eprintln!(
        "systemone edge requests: {requests_checked} checked, {rows_checked} rows, \
         {ids_compared} ids compared, {refusals_checked} refusals"
    );
}

#[test]
fn edge_answers_match_the_reference() {
    let Some((tokenizer, config)) = checkpoint("edge_answers_match_the_reference") else {
        return;
    };
    let labels = resolve_decision_labels(&tokenizer, config.max_options).expect("resolve labels");
    let fixtures: Vec<AnswerFixture> = read_jsonl(&fixture_dir().join("edge_answers.jsonl"));
    let mut checked = 0usize;
    for fixture in &fixtures {
        let prepared =
            prepare_request(&tokenizer, &labels, &config, &fixture.request_json).expect("accepted");
        let assembled = assemble(
            &prepared.rendered,
            &prepared.index,
            &fixture.probs,
            prepared.prompt.unique_tokens(),
        )
        .expect("assembles");
        let actual = serde_json::Value::Object(
            assembled
                .answers
                .iter()
                .map(|(key, value)| (key.clone(), value.to_serde_json()))
                .collect(),
        );
        compare_answers(&fixture.name, &fixture.answers, &actual);
        checked += 1;
    }
    eprintln!("systemone answers: {checked} compared");
}

#[test]
fn sample_population_reproduces_the_reference() {
    let Some((tokenizer, config)) = checkpoint("sample_population_reproduces_the_reference") else {
        return;
    };
    let Some(dir) = std::env::var_os(SAMPLE_DIR_ENV).map(PathBuf::from) else {
        eprintln!(
            "{SKIP_MARKER} test=sample_population_reproduces_the_reference \
             reason={SAMPLE_DIR_ENV} is unset (the gate-only population)"
        );
        return;
    };
    let requests_path = dir.join("sample_requests.jsonl");
    let answers_path = dir.join("sample_answers.jsonl");
    if !requests_path.is_file() || !answers_path.is_file() {
        eprintln!(
            "{SKIP_MARKER} test=sample_population_reproduces_the_reference \
             reason={} has no sample_requests.jsonl/sample_answers.jsonl",
            dir.display()
        );
        return;
    }
    let labels = resolve_decision_labels(&tokenizer, config.max_options).expect("resolve labels");
    let requests: Vec<RequestFixture> = read_jsonl(&requests_path);
    let mut requests_checked = 0usize;
    let mut rows_checked = 0usize;
    let mut ids_compared = 0usize;
    for fixture in &requests {
        requests_checked += 1;
        let prepared = prepare_request(&tokenizer, &labels, &config, &fixture.request_json)
            .unwrap_or_else(|error| panic!("{}: refused with {error}", fixture.name));
        let expected_rows = fixture.rows.as_ref().expect("sample fixture has rows");
        assert_eq!(
            prepared.prompt.rows.len(),
            expected_rows.len(),
            "{}: row count",
            fixture.name
        );
        for (row, expected) in prepared.prompt.rows.iter().zip(expected_rows) {
            assert_eq!(row.ids, expected.ids, "{}: ids", fixture.name);
            assert_eq!(row.slot, expected.slots[0], "{}: slot", fixture.name);
            assert_eq!(row.nopts, expected.nopts[0], "{}: nopts", fixture.name);
            rows_checked += 1;
            ids_compared += expected.ids.len();
        }
        assert_eq!(
            prepared.prompt.unique_tokens(),
            fixture
                .unique_tokens
                .expect("sample fixture has unique_tokens"),
            "{}: unique_tokens",
            fixture.name
        );
    }

    let answers: Vec<AnswerFixture> = read_jsonl(&answers_path);
    let mut answers_checked = 0usize;
    for fixture in &answers {
        let prepared =
            prepare_request(&tokenizer, &labels, &config, &fixture.request_json).expect("accepted");
        let assembled = assemble(
            &prepared.rendered,
            &prepared.index,
            &fixture.probs,
            prepared.prompt.unique_tokens(),
        )
        .expect("assembles");
        let actual = serde_json::Value::Object(
            assembled
                .answers
                .iter()
                .map(|(key, value)| (key.clone(), value.to_serde_json()))
                .collect(),
        );
        compare_answers(&fixture.name, &fixture.answers, &actual);
        answers_checked += 1;
    }
    eprintln!(
        "systemone sample population: {requests_checked} requests, {rows_checked} rows, \
         {ids_compared} ids compared, {answers_checked} answers"
    );
}

/// Whether an answer value matches the reference JSON, with keys and structure
/// identical and numbers equal to within [`NUMBER_TOLERANCE`].
fn compare_answers(name: &str, expected: &Value, actual: &Value) {
    match (expected, actual) {
        (Value::Number(left), Value::Number(right)) => {
            let left = left.as_f64().expect("number");
            let right = right.as_f64().expect("number");
            assert!(
                (left - right).abs() <= NUMBER_TOLERANCE,
                "{name}: {left} vs {right}"
            );
        }
        (Value::Object(left), Value::Object(right)) => {
            let left_keys: BTreeSet<&String> = left.keys().collect();
            let right_keys: BTreeSet<&String> = right.keys().collect();
            assert_eq!(left_keys, right_keys, "{name}: object keys");
            for (key, value) in left {
                compare_answers(name, value, &right[key.as_str()]);
            }
        }
        (Value::Array(left), Value::Array(right)) => {
            assert_eq!(left.len(), right.len(), "{name}: array length");
            for (left, right) in left.iter().zip(right) {
                compare_answers(name, left, right);
            }
        }
        (left, right) => assert_eq!(left, right, "{name}: value"),
    }
}

/// The reference's answer objects keep their keys in a fixed order; this pins
/// that our serialized object carries the same key set at the top level even if
/// the order the map was built in ever drifts.
#[test]
fn answer_value_to_serde_json_round_trips_a_map() {
    let mut map = IndexMap::new();
    map.insert("type".to_string(), AnswerValue::string("noul"));
    map.insert("noul".to_string(), AnswerValue::number(0.6292));
    let value = AnswerValue::Map(map);
    assert_eq!(
        value.to_serde_json(),
        serde_json::json!({"type": "noul", "noul": 0.6292})
    );
}
